def main():
    global MRCEM_TOPICS, SMLE_TOPICS
    MRCEM_TOPICS = MRCEM_TOPICS[:100]
    SMLE_TOPICS = SMLE_TOPICS[:100]

    print(f"Total MRCEM topics: {len(MRCEM_TOPICS)}")
    print(f"Total SMLE topics: {len(SMLE_TOPICS)}")

    assert len(MRCEM_TOPICS) == 100, f"Expected 100 MRCEM topics, got {len(MRCEM_TOPICS)}"
    assert len(SMLE_TOPICS) == 100, f"Expected 100 SMLE topics, got {len(SMLE_TOPICS)}"

    for title, subj, sys_name, snip, g_name, g_url in MRCEM_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    for title, subj, sys_name, snip, g_name, g_url in SMLE_TOPICS:
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {title}"
        assert g_url.startswith("https://"), f"Invalid url {g_url} in {title}"
        assert len(snip) > 20

    out_path = os.path.join(os.path.dirname(__file__), "mega41_topics_a.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 41 Topics Part A\n")
        f.write("# MRCEM (100 topics) + SMLE (100 topics)\n\n")
        f.write(f"MRCEM_TOPICS = {repr(MRCEM_TOPICS)}\n\n")
        f.write(f"SMLE_TOPICS = {repr(SMLE_TOPICS)}\n")
    print(f"Successfully generated {out_path}!")

if __name__ == "__main__":
    main()
